CREATE TABLE IF NOT EXISTS schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','operator','reviewer')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS electrolyte_formulations (id uuid PRIMARY KEY, name text NOT NULL, version integer NOT NULL, chemistry text NOT NULL, approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(name,version));
CREATE TABLE IF NOT EXISTS cell_lots (id uuid PRIMARY KEY, lot_code text UNIQUE NOT NULL, formulation_id uuid NOT NULL REFERENCES electrolyte_formulations(id), state text NOT NULL CHECK(state IN ('draft','qualified','released','hold')), nominal_capacity numeric NOT NULL, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modules (id uuid PRIMARY KEY, serial text UNIQUE NOT NULL, lot_id uuid NOT NULL REFERENCES cell_lots(id), state text NOT NULL CHECK(state IN ('assembled','testing','accepted','rejected')), version bigint NOT NULL DEFAULT 1, assembled_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS qualification_runs (id uuid PRIMARY KEY, lot_id uuid NOT NULL REFERENCES cell_lots(id), module_id uuid REFERENCES modules(id), state text NOT NULL CHECK(state IN ('planned','running','paused','succeeded','failed')), scheduled_at timestamptz NOT NULL, started_at timestamptz, finished_at timestamptz, attempts integer NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS measurements (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES qualification_runs(id), kind text NOT NULL CHECK(kind IN ('capacity','resistance','thermal','cycle')), value numeric NOT NULL, unit text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), recorded_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS quality_holds (id uuid PRIMARY KEY, lot_id uuid NOT NULL REFERENCES cell_lots(id), reason text NOT NULL, state text NOT NULL CHECK(state IN ('open','cleared')), opened_by uuid NOT NULL REFERENCES users(id), cleared_by uuid REFERENCES users(id), opened_at timestamptz NOT NULL DEFAULT now(), cleared_at timestamptz);
